
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_m05_2x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_m05_2x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.481205888322527e+00, -1.460214266103362e+00, -1.432947444399126e+00, -1.397495535859677e+00, -1.348672487517783e+00, -1.273490689209133e+00, -1.160433054160583e+00, -1.062503931874859e+00, -9.786247465524798e-01, -7.536738241306054e-01, -6.241779650829375e-01, -3.487262628267365e-01, -2.472776328208646e-01, -2.103258660306065e-01, -1.731893537626024e-01, -1.429824630767396e-01, -1.218057540196790e-01, -7.502083898935796e-02, -1.782692819554644e-02, -2.014012595659774e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


